-- By name and by zone map
WarZones.byName, WarZones.byMap = {}, {}
for _, zone in ipairs(WarZones.LIST) do
	WarZones.byName[zone.name] = zone
	WarZones.byMap[zone.mapId] = zone
end

---A zone by its name, or nil.
---@param name string?
---@return table?
function WarZones:Get(name)
	return name and WarZones.byName[name] or nil
end
